package ru.secondmemory;
import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import org.json.*;
public class MemorySearchTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 private void write(File dir,String...texts)throws Exception{try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(dir,"transcript.jsonl")),StandardCharsets.UTF_8)){for(int i=0;i<texts.length;i++)out.write(new JSONObject().put("text",texts[i]).put("saved_at","10:0"+i+":00").put("recorded_at",LocalDate.of(2026,10,20+i).atStartOfDay(ZoneId.of("UTC")).toInstant().toEpochMilli()).toString()+"\n");}}
 @Test public void findsForgottenFragmentWithoutDatePersonOrAnalysis()throws Exception{File root=temp.newFolder(),one=new File(root,"old-session"),two=new File(root,"other");assertTrue(one.mkdir());assertTrue(two.mkdir());write(one,"Нужно уточнить, куда отправили пакет документов.","Отправили заказным письмом, трек пока не сообщили.","Тогда запросим номер отправления завтра.");write(two,"Сегодня принесли обед.");List<MemorySearch.Doc> docs=MemorySearch.load(root);List<MemorySearch.Hit> hits=MemorySearch.find(docs,"заказное писмо",Collections.emptyList(),Long.MIN_VALUE,Long.MAX_VALUE);assertFalse(hits.isEmpty());assertEquals(one,hits.get(0).doc.dir);assertTrue(hits.get(0).doc.context.contains("номер отправления"));assertTrue(hits.get(0).doc.context.contains("куда отправили"));}
 @Test public void semanticTermsReachParaphrasesAndFilterDatesPerUtterance()throws Exception{File root=temp.newFolder(),dir=new File(root,"overnight");assertTrue(dir.mkdir());write(dir,"Пособие пока не поступило на счёт.","Сегодня обсуждали доставку бумаги.");List<MemorySearch.Doc> docs=MemorySearch.load(root);assertTrue(MemorySearch.find(docs,"где мои деньги",Collections.emptyList(),Long.MIN_VALUE,Long.MAX_VALUE).isEmpty());List<MemorySearch.Hit> hits=MemorySearch.find(docs,"где мои деньги",Arrays.asList("пособие","поступление","счёт"),Long.MIN_VALUE,Long.MAX_VALUE);assertEquals(1,hits.size());assertTrue(hits.get(0).doc.line.text.contains("Пособие"));RecallWindow day=new RecallWindow(LocalDate.of(2026,10,21),ZoneId.of("UTC"));assertTrue(MemorySearch.find(docs,"пособие",Collections.emptyList(),day.start,day.end).isEmpty());}
 @Test public void datesUseLocalCalendarAndExcludeNextMidnight(){RecallWindow day=new RecallWindow(LocalDate.of(2026,10,25),ZoneId.of("Europe/Helsinki"));assertEquals(25*3600000L,day.end-day.start);assertTrue(day.contains(day.start));assertFalse(day.contains(day.end));assertTrue(new RecallWindow(null,ZoneId.of("UTC")).contains(day.start));}
 @Test public void noMatchDoesNotInventResultsOrUseQuestionStopWords()throws Exception{File root=temp.newFolder(),dir=new File(root,"only");assertTrue(dir.mkdir());write(dir,"Сегодня погода отличная");assertTrue(MemorySearch.find(MemorySearch.load(root),"о чём мы говорили",Collections.emptyList(),Long.MIN_VALUE,Long.MAX_VALUE).isEmpty());assertTrue(MemorySearch.find(MemorySearch.load(root),"ампутация",Collections.emptyList(),Long.MIN_VALUE,Long.MAX_VALUE).isEmpty());}
}
